void update(int k, int l, int r, int i, int v) {   // a[i] = v
    if (i < l || r < i) return;
    if (l == r) { t[k] = v; return; }
    int m = (l + r) / 2;
    update(2 * k, l, m, i, v);
    update(2 * k + 1, m + 1, r, i, v);
    t[k] = t[2 * k] + t[2 * k + 1];
}
// 호출: update(1, 0, n - 1, i, v)

// n이 2의 거듭제곱일 때: 리프 a[i]는 노드 n + i
void update(int i, int v) {
    i += n;
    t[i] = v;
    while (i > 1) {
        i /= 2;                          // 부모로 올라간다
        t[i] = t[2 * i] + t[2 * i + 1];
    }
}

